# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor conv1_forward_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias);

torch::Tensor conv1_forward(torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
    TORCH_CHECK(bias.is_contiguous(), "bias must be contiguous");
    TORCH_CHECK(input.dim() == 4, "input must be 4D");
    TORCH_CHECK(input.size(1) == 3, "input channels must be 3");
    TORCH_CHECK(weight.sizes() == torch::IntArrayRef({96, 3, 11, 11}), "weight must be [96,3,11,11]");
    TORCH_CHECK(bias.sizes() == torch::IntArrayRef({96}), "bias must be [96]");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "weight must be float32");
    TORCH_CHECK(bias.scalar_type() == torch::kFloat32, "bias must be float32");
    return conv1_forward_cuda(input, weight, bias);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv1_forward", &conv1_forward, "Conv1 forward (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Tiled direct convolution kernel for:
//   input:  (N, 3, H, W)  NCHW float32
//   weight: (96, 3, 11, 11) float32
//   bias:   (96,) float32
//   stride=4, padding=2, dilation=1, groups=1
//   output: (N, 96, OH, OW)  where OH=(H+4-11)/4+1, OW=(W+4-11)/4+1

#define STRIDE 4
#define PAD    2
#define KH     11
#define KW     11
#define IC     3
#define OC     96

// Each thread computes one output element (n, oc, oh, ow).
__global__ void conv1_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int H, int W, int OH, int OW)
{
    // Grid: (N * OC, OH, OW) but flattened differently
    // blockDim: (32, 4, 1) -> threads cover (ow_tile, oh_tile, oc_tile)
    // We'll use a simple 1D grid over all output elements.
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * OC * OH * OW;
    if (idx >= total) return;

    int ow = idx % OW;
    int tmp = idx / OW;
    int oh = tmp % OH;
    tmp = tmp / OH;
    int oc = tmp % OC;
    int n  = tmp / OC;

    float acc = bias[oc];

    int ih_base = oh * STRIDE - PAD;
    int iw_base = ow * STRIDE - PAD;

    const float* w_ptr = weight + oc * (IC * KH * KW);
    const float* in_ptr = input + n * (IC * H * W);

    #pragma unroll
    for (int ic = 0; ic < IC; ic++) {
        const float* in_c = in_ptr + ic * (H * W);
        const float* w_c  = w_ptr  + ic * (KH * KW);
        #pragma unroll
        for (int kh = 0; kh < KH; kh++) {
            int ih = ih_base + kh;
            if (ih < 0 || ih >= H) continue;
            #pragma unroll
            for (int kw = 0; kw < KW; kw++) {
                int iw = iw_base + kw;
                if (iw < 0 || iw >= W) continue;
                acc += in_c[ih * W + iw] * w_c[kh * KW + kw];
            }
        }
    }

    output[n * (OC * OH * OW) + oc * (OH * OW) + oh * OW + ow] = acc;
}

torch::Tensor conv1_forward_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {
    int N  = input.size(0);
    int H  = input.size(2);
    int W  = input.size(3);
    int OH = (H + 2 * PAD - KH) / STRIDE + 1;
    int OW = (W + 2 * PAD - KW) / STRIDE + 1;

    auto output = torch::empty({N, OC, OH, OW}, input.options());

    int total = N * OC * OH * OW;
    int threads = 256;
    int blocks  = (total + threads - 1) / threads;

    conv1_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N, H, W, OH, OW
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        if (x.is_cuda and x.is_contiguous() and x.dim() == 4 and x.shape[1] == 3
                and self.conv1.weight.is_cuda and self.conv1.weight.is_contiguous()
                and self.conv1.bias is not None
                and self.conv1.bias.is_cuda and self.conv1.bias.is_contiguous()
                and tuple(self.conv1.weight.shape) == (96, 3, 11, 11)
                and self.conv1.stride == (4, 4)
                and self.conv1.padding == (2, 2)
                and self.conv1.dilation == (1, 1)
                and self.conv1.groups == 1
                and x.dtype == torch.float32):
            x = _stark_get_extension().conv1_forward(x, self.conv1.weight, self.conv1.bias)
        else:
            x = self.conv1(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        return x
        # <<<END_IMPROVE>>>

